cd /app && cat > image.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define W 2400
#define H 1800
#define SS 3
#define F 901.85
#define CAMH 1.5

/* scene */
static const double Cz=4.6, R=0.9775;        /* sphere center z, radius */
static const double Cx=0.0, Cy=0.9775;
static double L[3]={0.5875,0.55,0.4};
static const double AMB=0.2, KD=0.52, SHF=0.3175;
static const double MR=281.25, MG=55.125, MB=55.125;

static int clampi(double v){ v=v+0.5; if(v<0)v=0; if(v>255)v=255; return (int)v; }

int main(void){
    /* normalize light */
    double ln=sqrt(L[0]*L[0]+L[1]*L[1]+L[2]*L[2]);
    L[0]/=ln; L[1]/=ln; L[2]/=ln;
    char *buf=malloc((size_t)64*1024*1024);
    char *p=buf;
    p+=sprintf(p,"P3\n%d %d\n255\n",W,H);
    for(int py=0; py<H; py++){
        for(int px=0; px<W; px++){
            double ar=0,ag=0,ab=0;
            for(int sy=0; sy<SS; sy++) for(int sx=0; sx<SS; sx++){
                double fx=px+(sx+0.5)/SS;
                double fy=py+(sy+0.5)/SS;
                double dx=(fx-W/2.0)/F, dy=(H/2.0-fy)/F, dz=1.0;
                double n=sqrt(dx*dx+dy*dy+dz*dz); dx/=n;dy/=n;dz/=n;
                /* sphere */
                double ocx=-Cx, ocy=CAMH-Cy, ocz=-Cz;
                double b=2*(dx*ocx+dy*ocy+dz*ocz);
                double c=ocx*ocx+ocy*ocy+ocz*ocz-R*R;
                double disc=b*b-4*c, ts=1e9;
                if(disc>0){ double t=(-b-sqrt(disc))/2; if(t>1e-4) ts=t; }
                /* floor */
                double tf=1e9; if(dy<-1e-9) tf=-CAMH/dy;
                double r,g,bl;
                if(ts<tf && ts<1e8){
                    double hx=ts*dx, hy=CAMH+ts*dy, hz=ts*dz;
                    double nx=(hx-Cx)/R, ny=(hy-Cy)/R, nz=(hz-Cz)/R;
                    double nd=nx*L[0]+ny*L[1]+nz*L[2]; if(nd<0)nd=0;
                    double it=AMB+KD*nd;
                    r=MR*it; g=MG*it; bl=MB*it;
                }else if(tf<1e8){
                    double hx=tf*dx, hz=tf*dz;
                    int par=(((long)floor(hx))+((long)floor(hz)))&1;
                    double base= par? 152.0:67.0;
                    /* shadow ray toward light */
                    double sx_=hx-Cx, sy_=-Cy, sz_=hz-Cz;
                    double bb=2*(L[0]*sx_+L[1]*sy_+L[2]*sz_);
                    double cc=sx_*sx_+sy_*sy_+sz_*sz_-R*R;
                    double dd=bb*bb-4*cc;
                    if(dd>0 && (-bb-sqrt(dd))/2>1e-4) base*=SHF;
                    r=g=bl=base;
                }else{
                    r=158+33*fy/899.0; g=197+20*fy/899.0; bl=255;
                    if(r>255)r=255; if(g>255)g=255;
                }
                ar+=r; ag+=g; ab+=bl;
            }
            double inv=1.0/(SS*SS);
            p+=sprintf(p,"%d %d %d\n",clampi(ar*inv),clampi(ag*inv),clampi(ab*inv));
        }
    }
    FILE*fp=fopen("reconstructed.ppm","wb");
    fwrite(buf,1,p-buf,fp);
    fclose(fp);
    free(buf);
    return 0;
}
EOF
gcc -static -o image image.c -lm 2>&1 | head; echo "compiled $?"; cat image.c | gzip | wc -c
